"""Single-file Flask app with a health endpoint and X-Request-ID handling."""

import time
import uuid

from flask import Flask, jsonify, request

app = Flask(__name__)

_START_TIME = time.time()


@app.after_request
def add_request_id(response):
    """Attach an X-Request-ID header: echo the client's value if provided."""
    response.headers["X-Request-ID"] = (
        request.headers.get("X-Request-ID") or str(uuid.uuid4())
    )
    return response


@app.get("/healthz")
def healthz():
    return jsonify({"status": "ok", "uptime_seconds": time.time() - _START_TIME})


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)

